html:
{%- from "templates/print_formats/standard_macros.html" import add_header, render_field with context -%}

    <div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
        {% if letter_head and not no_letterhead %}
    		<div class="letter-head">{{ letter_head }}</div>
    	{% endif %}
    </div>
    <h1 class="pheading">
        إقرار ضريبة المبيعات
    </h1>
    <div class="divTable1">
        <table class="table1">
            <tr>
                <td class="txtRight txtBold">Invoice Issue Date :</td>
                <td class="txtCenter">{{doc.get_formatted("posting_date")}}</td>
                <td class="txtLeft txtBold">: تاريخ إصدار الفاتورة</td>
                <td class="txtRight txtBold">Invoice Number :</td>
                <td class="txtCenter">{{doc.name}}</td>
                <td class="txtLeft txtBold">: رقم الفاتورة</td>
            </tr>
            <tr>
                {% set cus_vat = frappe.get_doc('Customer', doc.customer_name) %}
                <td class="txtRight txtBold">Cust. TAX No:</td>
                <td class="txtCenter">{{cus_vat.custom_vat_registration_number  or ""}}</td>
                <td class="txtLeft txtBold">: الرقم الضريبي للعميل</td>

                <td class="txtRight txtBold">Salesman :</td>
                <td class="txtCenter">
                    {% for sales in doc.sales_team %}{{sales.sales_person}}  {%endfor%}</td>

                <td class="txtLeft txtBold">: المندوب</td>
            </tr>
            <tr>
                <td class="txtRight txtBold">Customer:</td>
                <td colspan="4" class="txtCenter txtBold">{{doc.customer_name}}</td>
                <td class="txtLeft txtBold">: العميل</td>
            </tr>
            <tr>
                <td class="txtRight txtBold">Address:</td>
                <td colspan="4" class="txtCenter txtBold">{{doc.customer_address or ""}}</td>
                <td class="txtLeft txtBold">: العنوان</td>
            </tr>
            <tr>
                <td class="txtRight txtBold">Note :</td>
                <td colspan="4" class="txtCenter txtBold">{{doc.custom_return_reason}}</td>
                <td class="txtLeft txtBold">: البيان</td>
            </tr>
        </table>
    </div>
    <!-- Table 2 start from here -->
    <table style="width: 100%;">
        <tr class="print-background" style="line-height: 15px;">
            <th class="txtCenter txtBold" style="width: 10%;"> النهائي
                Net
            </th>

            <th class="txtCenter txtBold" style="width: 10%;"> الخصم
                DISC
            </th>
            <th class="txtCenter txtBold" style="width: 14%;"> لإجمالي بدون
                الضريبة<br>
                Total
            </th>
            <th class="txtCenter txtBold" style="width: 14%;"> الإفرادي بدون
                الضريبة<br>
                Price
            </th>
            <th class="txtCenter txtBold" style="width: 10%;"> الكمية<br>
                Qty
            </th>
            <th class="txtCenter txtBold" style="width: 24%;"> البيـــــــــــــان<br>
                Discription
            </th>
        </tr>
        {%for item in doc.items%}
        <tr>
            <td style="width: 10%;" class="txtRight">{{item.get_formatted("net_amount")}}</td>



            <td style="width: 10%;" class="txtRight">{{item.get_formatted("discount_amount")}}</td>
            <td style="width: 10%;" class="txtRight">{{item.get_formatted("net_amount")}}</td>
            <td style="width: 10%;" class="txtRight">{{item.get_formatted("rate")}}</td>
            <td style="width: 10%;" class="txtCenter">{{item.qty}}</td>
            <td style="width: 40%;" class="txtRight txtBold">{{item.description}}</td>
        </tr>
        {%endfor%}
    </table>
    <!-- Table 3 start from here -->
    <div class="lastTableContent">
        <div class="lastTable">
            <table class="table3 txtRight">
                {%for tax in doc.taxes%}
                    <tr>
                        <td>{{ doc.get_formatted("total") }}</td>
                        <td class="txtBold print-background">الإجمالي ( غير شاملة ضريبة القيمة المضافة )</td>
                    </tr>
                    <tr>
                        <td>{{doc.get_formatted("discount_amount")}}</td>
                        <td class="txtBold print-background">الخصم</td>
                    </tr>
                    <tr>
                        <td> {{doc.get_formatted("total")}}</td>
                        <td class="txtBold print-background">الإجمالي الخاضع للضريبة 
                        <br>    (غير شاملة ضريبة القيمة المضافة )</td>
                    </tr>
                    <tr>
                        <td>{{ doc.get_formatted("total_taxes_and_charges") }}</td>
                        <td class="txtBold print-background">مجموع ضريبة القيمة المضافة %15</td>
                    </tr>
                {%endfor%}
                <tr>
                    <td>{{doc.get_formatted("grand_total")}}</td>
                    <td class="txtBold print-background">النهائي</td>
                </tr>
            </table>
        </div>
        <div class="qrCode">



             {% if doc.status!="Draft" %}

                    <img src="data:image/png;base64, {{ get_zatca_phase_1_qr_for_invoice(doc.name) }}" />

            {% endif %}
    <!--<img src={{doc.ksa_einv_qr}}>-->
</div>
    </div>
    <p class="txtBold">

        </p>
    <div class="witness">
        <p> Receiver : .................................... : المستلم</p>
        <p> Prepared by : .............................. : أعدت من قبل</p>
    </div>
{% if print_settings.repeat_header_footer %}
                <div id="footer-html">
                    {% if not no_letterhead and footer %}
                        <div class="letter-head-footer">
                            {{ footer }}
                        </div>
                    {% endif %}
                </div>
                {% endif %}

<style>
    .divTable1 {
         width: 100%;
         text-align: center;
        }
        .pheading {
            text-align: center;
        }
        .table1 {
            width: 100%;

        }
        table {
            font-size: 12px;
            margin-bottom: 8px;
        }
        table, tr, th, td {
            border: 1px solid #000;
            border-collapse: collapse;
            color: #000 !important;
        }
        .txtCenter {
            text-align: center;
        }
        .txtRight {
            text-align: right;
        }
        .txtLeft {
            text-align: left;
        }
        .txtBold {
            font-weight: bold !important;
        }
        .witness {
            display: flex;
            flex-direction: row;
            gap: 150px;
            margin-top: 60px;
        }
        .lastTableContent {
            display: flex;
            flex-direction: row;
            margin-top: 20px;
        }
        .lastTable {
            width: 50%;
        }
        .qrCode {
            width: 50%;
            text-align: center;
        }
      .qrCode img {
    margin-top: 33px;
    width: 150px;
    margin-left: 100px;
}html {
    direction: ltr;
 }       
@media print {
    .print-background {
        background-color: #F1F5FE;
    }
     #footer-html {
            position: fixed; bottom: 0; width: 100%;
        }
        html {
    direction: ltr;
}
</style>
